head.script:
scwin.log = function(msg) {
    var cur = txa_log.getValue();
    var ts = new Date().toLocaleTimeString();
    var line = "[" + ts + "] " + msg;
    txa_log.setValue(cur ? cur + "\n" + line : line);
};

scwin.onpageload = function() {
    dataMap_cfg.set("rowCount", "1000");
    dataMap_cfg.set("reportPrefix", "component.");
    scwin.log("페이지 로드 완료. 상단 '성능수집 ON' → 각 탭의 데이터 로드 → 'Report 조회' 순서로 테스트하세요.");
    scwin.log("현재 _performance.use = " + String(WebSquare._performance.use) + ", _on = " + String(WebSquare._performance._on));
};

/* ===== 수집 제어 (반드시 util.setPerformanceUse 사용 — 직접 use 대입 금지) ===== */
scwin.btn_perfOn_onclick = function() {
    WebSquare.util.setPerformanceUse(true);
    scwin.log("_performance ON — _on=" + String(WebSquare._performance._on) + ", maxEntries=" + WebSquare._performance.maxEntries + ", autoClean=" + String(WebSquare._performance.autoClean));
};
scwin.btn_perfOff_onclick = function() {
    WebSquare.util.setPerformanceUse(false);
    scwin.log("_performance OFF — _on=" + String(WebSquare._performance._on));
};
scwin.btn_clearBuffer_onclick = function() {
    WebSquare._performance.clearBuffer();
    scwin.log("clearBuffer() 호출 후 누적 measure entries = " + performance.getEntriesByType("measure").length);
};
scwin.btn_clearLog_onclick = function() {
    txa_log.setValue("");
};

/* ===== gridView ===== */
scwin.btn_grid_load_onclick = function() {
    var n = parseInt(dataMap_cfg.get("rowCount") || "1000", 10);
    var arr = [];
    for (var i = 0; i < n; i++) {
        arr.push({ ID: "ID_" + i, NAME: "Name_" + i, VALUE: i * 10, STATUS: (i % 2 === 0 ? "Y" : "N") });
    }
    dataList_grid.setJSON(arr);
    scwin.log("[gridView] dataList setJSON — " + n + "행");
};
scwin.btn_grid_direct_onclick = function() {
    var grd = grd_main;
    var n = parseInt(dataMap_cfg.get("rowCount") || "100", 10);
    var flat = [];
    for (var i = 0; i < n; i++) {
        flat.push("ID_" + i, "Name_" + i, i * 5, (i % 3 === 0 ? "A" : "B"));
    }
    grd.dataList.setData(flat, false, ["ID","NAME","VALUE","STATUS"]);
    scwin.log("[gridView] mappingController.setData(직접) — " + n + "행");
};
scwin.btn_grid_clear_onclick = function() {
    dataList_grid.setJSON([]);
    scwin.log("[gridView] 데이터 초기화");
};

/* ===== treeview ===== */
scwin.btn_tree_load_onclick = function() {
    var arr = [];
    var idx = 0;
    for (var a = 0; a < 5; a++) {
        arr.push({ value: "v_" + idx, label: "root_" + a, depth: "1" });
        idx++;
        for (var b = 0; b < 4; b++) {
            arr.push({ value: "v_" + idx, label: "child_" + a + "_" + b, depth: "2" });
            idx++;
        }
    }
    dataList_tree.setJSON(arr);
    scwin.log("[treeview] dataList setJSON — " + arr.length + " 노드");
};

/* ===== fusionchart ===== */
scwin.btn_chart_load_onclick = function() {
    if (typeof chart_fc === "undefined") {
        scwin.log("[fusionchart] chart_fc 컴포넌트 미확인 — 초기화 대기 필요");
        return;
    }
    var data = { data: [] };
    for (var i = 0; i < 10; i++) {
        data.data.push({ label: "Cat" + i, value: Math.floor(Math.random() * 100) });
    }
    chart_fc.setJSONData(data);
    scwin.log("[fusionchart] setJSONData — " + data.data.length + "건");
};

/* ===== fw차트 ===== */
scwin.btn_fw_bullet_onclick = function() {
    if (typeof chart_bullet === "undefined") {
        scwin.log("[fwBullet] 컴포넌트 미확인");
        return;
    }
    chart_bullet.setJSONData({
        chart: { caption: "Revenue", lowerLimit: "0", upperLimit: "100" },
        colorRange: { color: [{ minValue: "0", maxValue: "50", code: "f54336" }, { minValue: "50", maxValue: "100", code: "4caf50" }] },
        value: "70"
    });
    scwin.log("[fwBullet] setJSONData");
};
scwin.btn_fw_gauge_onclick = function() {
    if (typeof chart_gauge === "undefined") {
        scwin.log("[fwGauge] 컴포넌트 미확인");
        return;
    }
    chart_gauge.setJSONData({
        chart: { caption: "Pressure", lowerLimit: "0", upperLimit: "100" },
        colorRange: { color: [{ minValue: "0", maxValue: "100", code: "4caf50" }] },
        dials: { dial: [{ value: "65" }] }
    });
    scwin.log("[fwGauge] setJSONData");
};

/* ===== Report / Raw ===== */
scwin.btn_report_onclick = function() {
    var rep = WebSquare._performance.getReport();
    scwin.log("── _performance.getReport() ──");
    scwin.log("  bootstrap keys: " + Object.keys(rep.bootstrap).length);
    scwin.log("  wframe entries: " + rep.wframe.length);
    scwin.log("  components:");
    for (var type in rep.components) {
        var arr = rep.components[type];
        var total = 0;
        for (var k = 0; k < arr.length; k++) total += arr[k].duration;
        scwin.log("    " + type + " : " + arr.length + "건, 총 " + total.toFixed(1) + "ms");
        for (var k = 0; k < Math.min(3, arr.length); k++) {
            scwin.log("      - " + arr[k].name + " : " + arr[k].duration.toFixed(2) + "ms");
        }
    }
    scwin.log("  dataCollection entries: " + rep.dataCollection.length);
};
scwin.btn_raw_onclick = function() {
    var prefix = dataMap_cfg.get("reportPrefix") || "component.";
    var arr = performance.getEntriesByType("measure").filter(function(e) {
        return e.name.indexOf("wq." + prefix) === 0;
    });
    scwin.log("── wq." + prefix + "* measures — " + arr.length + "건 ──");
    for (var i = 0; i < Math.min(arr.length, 40); i++) {
        scwin.log("  " + arr[i].name + " : " + arr[i].duration.toFixed(2) + "ms");
    }
};

/* ===== tabControl ===== */
scwin.tab_main_onchange = async function(info) {
    scwin.log("[tabControl] onchange " + info.oldIndex + " → " + info.newIndex);
};
